// Scale up the entire play icon badge container on thumbnail cards
element.style.transform = 'scale(2)';
element.style.transformOrigin = 'bottom left';

// Make the inline video stroke icons in list rows larger
element.style.width = '28px';
element.style.height = '28px';
element.style.minWidth = '28px';
element.style.minHeight = '28px';
element.style.flexShrink = '0';

// Increase the font size of video list item titles
element.style.fontSize = '15px';
element.style.fontWeight = '600';
element.style.lineHeight = '1.4';

// Increase font size of media card titles
element.style.fontSize = '15px';
element.style.fontWeight = '600';

// Only act once — if we've already injected the video, skip
if (element.dataset.videoInjected === 'true') return;

// Find the image element to extract the content slug for a video URL
const img = element.querySelector('img.Image--intrinsicRatioElement--bFd9O');
if (!img) return;

// Check if the image src looks like a static map graphic (staticmaps or forecast map patterns)
const src = img.src || img.getAttribute('data-src') || '';

// Get the link href from the anchor inside the primary container
const anchor = element.querySelector('a.MediaObject--mediaLink--8jZq+, a.mediaLink');
if (!anchor) return;

const href = anchor.href || '';
// Only proceed if there's a real content link (not a map-only card)
if (!href) return;

// Build an autoplay video element that mimics the intrinsic ratio container
const imgWrapper = img.closest('.Image--intrinsicRatioRoot--L7BRj');
if (!imgWrapper) return;

// Create the video element
const video = document.createElement('video');
video.autoplay = true;
video.muted = true;
video.loop = true;
video.playsInline = true;
video.controls = true;
video.style.position = 'absolute';
video.style.top = '0';
video.style.left = '0';
video.style.width = '100%';
video.style.height = '100%';
video.style.objectFit = 'cover';
video.style.borderRadius = 'inherit';
video.style.zIndex = '5';
video.style.background = '#000';

// Use the TWC video stream URL pattern derived from the article href
// TWC serves HLS/mp4 for video articles via their CDN
// Extract the path segment for the video ID
const pathMatch = href.match(/\/([^/]+)$/);
const slug = pathMatch ? pathMatch[1] : '';

// TWC video embed pattern
const videoSrc = `https://dsx.weather.com/util/image/map/forecasts/radar_animated.gif`;

// Instead of trying to find a video src (which requires auth),
// we auto-click the primary card link to launch the video player
// But first, set up a play overlay button styled prominently
const overlay = element.querySelector('.MediaObject--overlay--wu6Hj');
if (overlay) {
  overlay.style.background = 'linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.1) 60%, transparent 100%)';
  overlay.style.display = 'flex';
  overlay.style.alignItems = 'center';
  overlay.style.justifyContent = 'center';
  overlay.style.cursor = 'pointer';
  overlay.style.zIndex = '10';
  overlay.style.borderRadius = '8px';

  // Only add the button once
  if (!overlay.querySelector('.custom-autoplay-btn')) {
    const btn = document.createElement('button');
    btn.className = 'custom-autoplay-btn';
    btn.setAttribute('aria-label', 'Play video');
    btn.style.cssText = `
      background: rgba(0,120,200,0.92);
      border: none;
      border-radius: 50%;
      width: 72px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      box-shadow: 0 4px 20px rgba(0,0,0,0.5);
      transition: transform 0.15s, background 0.15s;
      animation: pulse-play 2s ease-in-out infinite;
    `;

    // Add a style tag for the pulse animation once
    if (!document.getElementById('custom-autoplay-style')) {
      const style = document.createElement('style');
      style.id = 'custom-autoplay-style';
      style.textContent = `
        @keyframes pulse-play {
          0%, 100% { transform: scale(1); box-shadow: 0 4px 20px rgba(0,0,0,0.5); }
          50% { transform: scale(1.08); box-shadow: 0 6px 28px rgba(0,100,200,0.7); }
        }
        .custom-autoplay-btn:hover { background: rgba(0,160,255,0.98) !important; transform: scale(1.12) !important; }
      `;
      document.head.appendChild(style);
    }

    // Triangle play icon SVG
    btn.innerHTML = `<svg viewBox="0 0 24 24" width="30" height="30" fill="white"><path d="M8 5v14l11-7z"/></svg>`;

    // Clicking the overlay play button navigates to the video article
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      anchor.click();
    });

    overlay.appendChild(btn);
  }
}

element.dataset.videoInjected = 'true';
